{"task": "Find all log messages containing date patterns in YYYY/MM/DD format", "sql": "SELECT * FROM logs WHERE regexp_like(message, '/[0-9]{4}/[0-9]{2}/[0-9]{2}/')"}
{"task": "Count error logs that mention dates in URL paths", "sql": "SELECT count(*) as date_error_count FROM logs WHERE level = 'ERROR' AND regexp_like(message, '/[0-9]{4}/[0-9]{2}/[0-9]{2}/')"}
{"task": "Identify distinct services with date-containing log messages", "sql": "SELECT DISTINCT service FROM logs WHERE regexp_like(message, '/[0-9]{4}/[0-9]{2}/[0-9]{2}/')"}
{"task": "Find HTTP paths that contain valid date patterns from events table", "sql": "SELECT path FROM events WHERE regexp_like(path, '/[0-9]{4}/[0-9]{2}/[0-9]{2}/')"}
{"task": "List all log entries with dates in message and their timestamps", "sql": "SELECT ts, level, message FROM logs WHERE regexp_like(message, '[0-9]{4}/[0-9]{2}/[0-9]{2}') ORDER BY ts DESC"}
{"task": "Count requests with date patterns grouped by status code", "sql": "SELECT status, count(*) as request_count FROM events WHERE regexp_like(path, '/[0-9]{4}/[0-9]{2}/[0-9]{2}/') GROUP BY status"}
{"task": "Find log messages that contain dates in different formats (YYYY-MM-DD)", "sql": "SELECT * FROM logs WHERE regexp_like(message, '[0-9]{4}-[0-9]{2}-[0-9]{2}') OR regexp_like(message, '/[0-9]{4}/[0-9]{2}/[0-9]{2}/')"}
{"task": "Show events with date patterns and their user IDs", "sql": "SELECT id, user_id, path FROM events WHERE regexp_like(path, '[0-9]{4}/[0-9]{2}/[0-9]{2}') AND status = 200"}
{"task": "Find log entries where message contains a date followed by common API endpoints", "sql": "SELECT * FROM logs WHERE regexp_like(message, '/[0-9]{4}/[0-9]{2}/[0-9]{2}/api/')"}
{"task": "Identify services that have requests with dates in paths and error levels", "sql": "SELECT DISTINCT l.service FROM logs l JOIN events e ON regexp_like(e.path, '/[0-9]{4}/[0-9]{2}/[0-9]{2}/') WHERE l.level = 'ERROR' AND regexp_like(l.message, '[0-9]{4}/[0-9]{2}/[0-9]{2}')"}

